arguments.command:
powershell -Command "
Add-Type -AssemblyName UIAutomationClient;
Add-Type -AssemblyName UIAutomationTypes;
Start-Sleep -Seconds 3;

# Find Chrome window
$chrome = Get-Process -Name chrome | Where-Object { $_.MainWindowTitle -ne '' } | Select-Object -First 1;
if ($chrome) {
    Write-Host 'Chrome found with PID:' $chrome.Id;
    Start-Sleep -Seconds 2;
} else {
    Write-Host 'Chrome process not found with main window';
}
"
